package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.deser.DeserializationContext;
import com.fasterxml.jackson.databind.deser.PropertyBasedCreator;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.impl.PropertyValueBuffer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.TokenBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class ExternalTypeHandler_complete_TriageGen1Test {

    private JsonParser p;
    private DeserializationContext ctxt;
    private PropertyValueBuffer buffer;
    private PropertyBasedCreator creator;
    private JavaType beanType;

    @Before
    public void setUp() {
        p = mock(JsonParser.class);
        ctxt = mock(DeserializationContext.class);
        buffer = mock(PropertyValueBuffer.class);
        creator = mock(PropertyBasedCreator.class);
        beanType = mock(JavaType.class);
    }

    /**
     * Helper to create a mock ExtTypedProperty
     */
    private ExtTypedProperty createMockExtProp(SettableBeanProperty prop, boolean hasDefaultType, String defaultTypeId, String typePropName) {
        ExtTypedProperty extProp = mock(ExtTypedProperty.class);
        when(extProp.getProperty()).thenReturn(prop);
        when(extProp.hasDefaultType()).thenReturn(hasDefaultType);
        when(extProp.getDefaultTypeId()).thenReturn(defaultTypeId);
        when(extProp.getTypePropertyName()).thenReturn(typePropName);
        return extProp;
    }

    /**
     * Helper to create a mock SettableBeanProperty
     */
    private SettableBeanProperty createMockProp(String name, int creatorIndex) {
        SettableBeanProperty prop = mock(SettableBeanProperty.class);
        when(prop.getName()).thenReturn(name);
        when(prop.getCreatorIndex()).thenReturn(creatorIndex);
        return prop;
    }

    @Test
    public void testComplete_Success_AllPaths() throws IOException {
        // Property 0: Creator property (index 0)
        SettableBeanProperty prop0 = createMockProp("prop0", 0);
        ExtTypedProperty extProp0 = createMockExtProp(prop0, false, null, "typeProp0");

        // Property 1: Non-creator property (index -1)
        SettableBeanProperty prop1 = createMockProp("prop1", -1);
        ExtTypedProperty extProp1 = createMockExtProp(prop1, false, null, "typeProp1");

        ExtTypedProperty[] properties = new ExtTypedProperty[]{extProp0, extProp1};
        String[] typeIds = new String[]{"type0", null};
        com.fasterxml.jackson.core.io.TokenBuffer[] tokens = new com.fasterxml.jackson.core.io.TokenBuffer[]{null, null};

        // Mocking Internal _deserialize via a subclass/spy because it's protected/internal
        ExternalTypeHandler handler = spy(new ExternalTypeHandler(beanType, properties, new HashMap<>(), typeIds, tokens) {
            @Override
            protected Object _deserialize(JsonParser p, DeserializationContext ctxt, int index, String typeId) throws IOException {
                if (index == 0) return "val0";
                if (index == 1) return "val1";
                return null;
            }
        });

        Object mockBean = new Object();
        when(creator.build(ctxt, buffer)).thenReturn(mockBean);

        Object result = handler.complete(p, ctxt, buffer, creator);

        // Verify creator assignment
        verify(buffer).assignParameter(prop0, "val0");
        // Verify non-creator assignment
        verify(prop1).set(mockBean, "val1");
        assertEquals(mockBean, result);
    }

    @Test
    public void testComplete_WithCreatorTypeProperty() throws IOException {
        SettableBeanProperty prop0 = createMockProp("prop0", 0);
        SettableBeanProperty typeProp0 = createMockProp("typeProp0", 1);
        ExtTypedProperty extProp0 = createMockExtProp(prop0, false, null, "typePropName");
        when(extProp0.getTypeProperty()).thenReturn(typeProp0);

        ExtTypedProperty[] properties = new ExtTypedProperty[]{extProp0};
        String[] typeIds = new String[]{"typeId0"};
        com.fasterxml.jackson.core.io.TokenBuffer[] tokens = new com.fasterxml.jackson.core.io.TokenBuffer[]{null};

        ExternalTypeHandler handler = spy(new ExternalTypeHandler(beanType, properties, new HashMap<>(), typeIds, tokens) {
            @Override
            protected Object _deserialize(JsonParser p, DeserializationContext ctxt, int index, String typeId) throws IOException {
                return "val0";
            }
        });

        Object mockBean = new Object();
        when(creator.build(ctxt, buffer)).thenReturn(mockBean);

        handler.complete(p, ctxt, buffer, creator);

        verify(buffer).assignParameter(prop0, "val0");
        verify(buffer).assignParameter(typeProp0, "typeId0");
    }

    @Test
    public void testComplete_MissingTypeId_UsesDefault() throws IOException {
        SettableBeanProperty prop0 = createMockProp("prop0", -1);
        ExtTypedProperty extProp0 = createMockExtProp(prop0, true, "defaultId", "typePropName");

        ExtTypedProperty[] properties = new ExtTypedProperty[]{extProp0};
        String[] typeIds = new String[]{null};
        // token is not null, but typeId is null -> trigger default type logic
        com.fasterxml.jackson.core.io.TokenBuffer[] tokens = new com.fasterxml.jackson.core.io.TokenBuffer[]{mock(com.fasterxml.jackson.core.io.TokenBuffer.class)};

        ExternalTypeHandler handler = spy(new ExternalTypeHandler(beanType, properties, new HashMap<>(), typeIds, tokens) {
            @Override
            protected Object _deserialize(JsonParser p, DeserializationContext ctxt, int index, String typeId) throws IOException {
                assertEquals("defaultId", typeId);
                return "val0";
            }
        });

        when(creator.build(ctxt, buffer)).thenReturn(new Object());
        handler.complete(p, ctxt, buffer, creator);
    }

    @Test(expected = IOException.class)
    public void testComplete_MissingTypeId_ReportsError() throws IOException {
        SettableBeanProperty prop0 = createMockProp("prop0", -1);
        ExtTypedProperty extProp0 = createMockExtProp(prop0, false, null, "typePropName");

        ExtTypedProperty[] properties = new ExtTypedProperty[]{extProp0};
        String[] typeIds = new String[]{null};
        com.fasterxml.jackson.core.io.TokenBuffer[] tokens = new com.fasterxml.jackson.core.io.TokenBuffer[]{mock(com.fasterxml.jackson.core.io.TokenBuffer.class)};

        ExternalTypeHandler handler = spy(new ExternalTypeHandler(beanType, properties, new HashMap<>(), typeIds, tokens) {
            @Override
            protected Object _deserialize(JsonParser p, DeserializationContext ctxt, int index, String typeId) throws IOException {
                return null;
            }
        });

        doThrow(new IOException()).when(ctxt).reportInputMismatch(any(), anyString(), anyString());

        handler.complete(p, ctxt, buffer, creator);
    }

    @Test(expected = IOException.class)
    public void testComplete_MissingPropertyForTypeId_ReportsError() throws IOException {
        SettableBeanProperty prop0 = createMockProp("prop0", -1);
        ExtTypedProperty extProp0 = createMockExtProp(prop0, false, null, "typePropName");

        ExtTypedProperty[] properties = new ExtTypedProperty[]{extProp0};
        String[] typeIds = new String[]{"someId"};
        // token is null but typeId is present -> triggers error
        com.fasterxml.jackson.core.io.TokenBuffer[] tokens = new com.fasterxml.jackson.core.io.TokenBuffer[]{null};

        ExternalTypeHandler handler = spy(new ExternalTypeHandler(beanType, properties, new HashMap<>(), typeIds, tokens) {
            @Override
            protected Object _deserialize(JsonParser p, DeserializationContext ctxt, int index, String typeId) throws IOException {
                return null;
            }
        });

        doThrow(new IOException()).when(ctxt).reportInputMismatch(any(), anyString(), anyString());

        handler.complete(p, ctxt, buffer, creator);
    }

    @Test
    public void testComplete_SkipEmptyProperties() throws IOException {
        SettableBeanProperty prop0 = createMockProp("prop0", -1);
        ExtTypedProperty extProp0 = createMockExtProp(prop0, false, null, "typePropName");

        ExtTypedProperty[] properties = new ExtTypedProperty[]{extProp0};
        String[] typeIds = new String[]{null};
        // Both typeId and token are null
        com.fasterxml.jackson.core.io.TokenBuffer[] tokens = new com.fasterxml.jackson.core.io.TokenBuffer[]{null};

        ExternalTypeHandler handler = spy(new ExternalTypeHandler(beanType, properties, new HashMap<>(), typeIds, tokens) {
            @Override
            protected Object _deserialize(JsonParser p, DeserializationContext ctxt, int index, String typeId) throws IOException {
                return null;
            }
        });

        Object mockBean = new Object();
        when(creator.build(ctxt, buffer)).thenReturn(mockBean);

        handler.complete(p, ctxt, buffer, creator);

        // Verify _deserialize was never called because it was skipped
        verify(handler, never())._deserialize(any(), any(), anyInt(), any());
        // Verify prop.set was never called because values[i] remains null 
        // (actually the loop for non-creator properties runs, but values[i] is null)
        // In the code: values[i] = _deserialize... if skipped, values[i] is null. 
        // However, the first loop 'continue' skips the assignment.
        // Let's check if prop.set is called with null.
        verify(prop0, times(1)).set(mockBean, null);
    }
}
